static inline struct crypto_alg *crypto_alg_get(struct crypto_alg *alg) /* <=== crypto_alg_get */ 
{
	refcount_inc(&alg->cra_refcnt);
	return alg;
}

static inline void *nlmsg_data(const struct nlmsghdr *nlh) /* <=== nlmsg_data */ 
{
	return (unsigned char *) nlh + NLMSG_HDRLEN;
}

struct crypto_alg *crypto_alg_match(struct crypto_user_alg *p, int exact) /* <=== crypto_alg_match */ 
{
	struct crypto_alg *q, *alg = NULL;

	down_read(&crypto_alg_sem);

	list_for_each_entry(q, &crypto_alg_list, cra_list) {
		int match = 0;

		if (crypto_is_larval(q))
			continue;

		if ((q->cra_flags ^ p->cru_type) & p->cru_mask)
			continue;

		if (strlen(p->cru_driver_name))
			match = !strcmp(q->cra_driver_name,
					p->cru_driver_name);
		else if (!exact)
			match = !strcmp(q->cra_name, p->cru_name);

		if (!match)
			continue;

		if (unlikely(!crypto_mod_get(q)))
			continue;

		alg = q;
		break;
	}

	up_read(&crypto_alg_sem);

	return alg;
}

static inline int nlmsg_total_size(int payload) /* <=== nlmsg_total_size */ 
{
	return NLMSG_ALIGN(nlmsg_msg_size(payload));
}

static inline int nlmsg_msg_size(int payload) /* <=== nlmsg_msg_size */ 
{
	return NLMSG_HDRLEN + payload;
}

static inline struct sk_buff *nlmsg_new(size_t payload, gfp_t flags) /* <=== nlmsg_new */ 
{
	return alloc_skb(nlmsg_total_size(payload), flags);
}

struct crypto_alg *crypto_mod_get(struct crypto_alg *alg) /* <=== crypto_mod_get */ 
{
	return try_module_get(alg->cra_module) ? crypto_alg_get(alg) : NULL;
}

static inline int crypto_is_larval(struct crypto_alg *alg) /* <=== crypto_is_larval */ 
{
	return alg->cra_flags & CRYPTO_ALG_LARVAL;
}

static inline bool try_module_get(struct module *module) /* <=== try_module_get */ 
{
	return true;
}

static inline int nlmsg_unicast(struct sock *sk, struct sk_buff *skb, u32 portid) /* <=== nlmsg_unicast */ 
{
	int err;

	err = netlink_unicast(sk, skb, portid, MSG_DONTWAIT);
	if (err > 0)
		err = 0;

	return err;
}

